const config = $input.first().json;
if (!config.enabled) return [];
if (config.analysisMode !== 'manual') throw new Error('Este flujo usa IA manual; no admite llamadas automáticas.');
if (!Array.isArray(config.targets)) throw new Error('targets debe ser un array.');
if (!config.targets.length) return [];
const uuid = /^(?:[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i;
if (!uuid.test(config.pipelineDataSourceId)) throw new Error('Falta un data_source_id válido del Pipeline.');
if (!/^[a-zA-Z0-9_-]{1,32}$/.test(config.campaign)) throw new Error('campaign inválida.');
if (!Number.isInteger(config.maxPerRun) || config.maxPerRun < 1 || config.maxPerRun > 10)
  throw new Error('maxPerRun debe ser un entero entre 1 y 10.');
const output = [];
const seen = new Set();
if (config.targets.length > 100) throw new Error('Máximo 100 objetivos revisados en esta cola local.');
for (const t of config.targets) {
  if (t.approved !== true) continue;
  // Intentionally accept origins only, without ports, credentials, queries or paths.
  // This lexical check is NOT DNS/redirect/subresource egress isolation.
  const match = /^https:\/\/([a-z0-9.-]+)\/?$/i.exec(String(t.url || ''));
  if (!match) throw new Error('Solo homepages HTTPS públicas: https://dominio.com/');
  const host = match[1].toLowerCase();
  const labels = host.split('.');
  if (host.length > 253 || labels.length < 2 || !/^[a-z]{2,63}$/.test(labels.at(-1)) ||
      labels.some(l => !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(l)) ||
      /(?:^|\.)(?:localhost|local|internal|test|example|invalid|onion|home|lan)$/.test(host))
    throw new Error('Hostname no permitido.');
  if (!uuid.test(t.nichePageId)) throw new Error('nichePageId debe ser el ID de una página del Radar.');
  if (!['video', 'automation'].includes(t.service)) throw new Error('service: video o automation.');
  const company = String(t.company || '').trim();
  if (!company || company.length > 120) throw new Error('company: entre 1 y 120 caracteres.');
  const key = `${host.replace(/^www\./, '')}|${t.nichePageId.replace(/-/g, '').toLowerCase()}|${config.campaign}`;
  if (seen.has(key)) continue;
  seen.add(key);
  output.push({json: {
    company, url: `https://${host}/`, host, nichePageId: t.nichePageId,
    service: t.service, key, pipelineDataSourceId: config.pipelineDataSourceId,analysisMode:config.analysisMode
  }, pairedItem: {item: 0}});
}
return output;

